<script setup lang="ts">const {lang}=useLocale(); const {data:countries}=await useFetch<any[]>('/api/catalog/countries'); const q=ref(''); const filtered=computed(()=>countries.value?.filter(c=>`${c.nameRu} ${c.nameEn} ${c.phoneCode}`.toLowerCase().includes(q.value.toLowerCase()))||[]); usePageSeo(computed(()=>lang.value==='ru'?'Виртуальные номера по странам':'Virtual numbers by country'),computed(()=>lang.value==='ru'?'Выберите страну для просмотра публичных временных номеров и SMS.':'Choose a country to browse public temporary numbers and SMS.'))</script>
<template><div class="shell page"><span class="kicker">Catalog / 195</span><h1>{{lang==='ru'?'Номера по странам':'Numbers by country'}}</h1><p class="lead">{{lang==='ru'?'Найдите нужное телефонное направление в полном каталоге. Флаги и коды помогут быстро сориентироваться.':'Find the calling destination you need in the complete catalog. Flags and dialing codes make browsing quick.'}}</p><input v-model="q" class="search" :placeholder="lang==='ru'?'Поиск страны или кода…':'Search country or code…'"><div class="card-grid"><CountryCard v-for="c in filtered" :key="c.id" :country="c"/></div></div></template>
